import { ProductCard } from "@/components/product-card";
import { listProducts } from "@/lib/products";

export default async function ProductsPage() {
  const products = await listProducts();
  return (
    <section>
      <h1 className="text-2xl font-semibold">All products</h1>
      <ul className="grid gap-4 sm:grid-cols-3">
        {products.map((product) => (
          <ProductCard key={product.slug} product={product} />
        ))}
      </ul>
    </section>
  );
}

export async function listProducts(category?: string) {
  "use cache";
  cacheLife("hours");
  cacheTag("products");
  const query = category ? `?category=${encodeURIComponent(category)}` : "";
  const page = await apiFetch(`/products${query}`);
  return z.object({ items: z.array(ProductSummarySchema) }).parse(page).items;
}

export async function getProduct(slug: string): Promise<Product | null> {
  "use cache";
  cacheLife("hours");
  cacheTag(`product-${slug}`);
  try {
    return ProductSchema.parse(await apiFetch(`/products/${slug}`));
  } catch (error) {
    if (error instanceof ApiError && error.status === 404) return null;
    throw error;
  }
}

export async function getReviews(slug: string) {
  "use cache";
  cacheLife("minutes");
  cacheTag(`reviews-${slug}`);
  try {
    const page = await apiFetch(`/products/${slug}/reviews`);
    return z.object({ items: z.array(ReviewSchema) }).parse(page).items;
  } catch (error) {
    if (error instanceof ApiError && error.status === 404) return [];
    throw error;
  }
}

export async function getStock(slug: string) {
  const product = ProductSchema.parse(await apiFetch(`/products/${slug}`));
  return product.stock;
}

import { apiFetch } from "@/lib/api";

async function getCart() {
  "use cache";
  return apiFetch("/cart", { session: true });
}

